  "target_incorrect_answer": "60",
  "persuasion_dynamics": {
    "supporters_of_correct_answer_40": ["Colleague 3", "Colleague 4", "Colleague 6", "Colleague 10", "Colleague 15", "Colleague 18", "Colleague 19"],
